private void GroupHeader2_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
GroupHeaderBand p = (GroupHeaderBand ) sender;
 XtraReport report = (XtraReport)p.Report;

 System.Data.DataSet ds = ((System.Data.DataSet)report.DataSource);
            if (ds.Tables[0].Rows.Count != 0 && ds != null)
            {

               xrChart1.DataSource = ds;
               xrChart1.DataAdapter = report.DataAdapter;
               xrChart1.Series.Clear();
              konfiguroSeries(sender,"", ds.Tables[0], ScaleType.Qualitative, "RRESHTI", ScaleType.Numerical, "VLERA", true);}

}

 public void konfiguroSeries(object sender,string emri, System.Data.DataTable datasource, ScaleType argScale, string argMember, ScaleType valScale, string valMember, bool labelVisible)
        {

 GroupHeaderBand p = (GroupHeaderBand ) sender;
 XtraReport report = (XtraReport)p.Report;

            DevExpress.XtraCharts.ViewType type = ((ViewType)Enum.Parse(typeof(ViewType), "Bar"));
            Series series = new Series(emri , type);
            series.DataSource = datasource;
            series.ArgumentScaleType = argScale;
            series.ArgumentDataMember = argMember;
            series.ValueScaleType = valScale;
            series.ValueDataMembers.AddRange(new string[] { valMember }); 
            series.Label.TextPattern = "{V}" + " Lek"; 
            series.Label.Border.Visibility = DefaultBoolean.False;
            series.Label.Font = new Font("Times New Roman", 10, FontStyle.Bold);
            series.Label.TextColor = Color.Black;
           ((BarSeriesLabel)(series.Label)).Position = BarSeriesLabelPosition.Top;  
           ((BarSeriesLabel)(series.Label)).ShowForZeroValues= true;  


            xrChart1.Series.Add(series);       
        }


private void xrTableCell1_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
if (GetCurrentColumnValue("NR").ToString() == "RBV1")

xrTableCell1.Visible = false;
else 
xrTableCell1.Visible = true;
}

