private void xrChart1_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
XRChart xrc = (XRChart)sender;

    string filter_value = GetCurrentColumnValue("BASHKIA").ToString();

    xrc.Series[0].DataFilters.Clear();

    xrc.Series[0].DataFilters.Add(new DataFilter("BASHKIA", "System.String", 
        DataFilterCondition.Equal, filter_value));
xrc.Series[0].DataFilters.Add(new DataFilter("NR", "System.String", 
        DataFilterCondition.NotEqual, "RBV1"));


}

private void xrLabel9_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
if (GetCurrentColumnValue("NR").ToString() == "RBV1")
xrLabel9.Text = Convert.ToDouble(GetCurrentColumnValue("VLERA")).ToString("#,#0.00");
}


private void xrTableCell4_SummaryRowChanged(object sender, System.EventArgs e) {
  if (GetCurrentColumnValue("NR").ToString() == "RBV1"){
 vlera = Convert.ToInt64(GetCurrentColumnValue("VLERA"));}
sum += Convert.ToInt64(GetCurrentColumnValue("VLERA"));

}

private void xrTableCell4_SummaryReset(object sender, System.EventArgs e) {
sum = 0;
}


private void xrTableCell4_SummaryGetResult(object sender, DevExpress.XtraReports.UI.SummaryGetResultEventArgs e) {
e.Result = sum - vlera;
e.Handled = true;
}

